import { useAccessibility } from "intelliaccess-framework";

const profiles = [
  { key: "lowVision", label: "Low Vision" },
  { key: "dyslexia", label: "Dyslexia" },
  { key: "colourBlind", label: "Colour Blind" },
  { key: "elderly", label: "Elderly" },
];

function Navbar() {
  const { profile, setProfile } = useAccessibility();

  const activeLabel = profiles.find((p) => p.key === profile)?.label || "None";

  return (
    <nav className="navbar">
      <h2>Student Notice Board</h2>

      <p className="selector-label">Select your accessibility preference:</p>

      <div className="navbar-buttons">
        {profiles.map((p) => (
          <button
            key={p.key}
            onClick={() => setProfile(p.key)}
            className={profile === p.key ? "active" : ""}
          >
            {p.label}
          </button>
        ))}
        <button onClick={() => setProfile("none")}>Reset</button>
      </div>

      <p className="active-indicator">
        Currently active: <strong>{activeLabel}</strong>
      </p>
    </nav>
  );
}

export default Navbar;
